// show attribute in PropertyGrid	[CategoryAttribute("KOMPONENTY"),		DisplayName("Vrstva2"),		DescriptionAttribute("Upravit vrstvu2"),		TypeConverter(typeof(ListObjectCollectionConverter))	]	ListObjectCollection ListObjectCollection { get; set; }	//manage selection	public ListObjectCollection ListObjectCollection {		get { 			var names = new ImageLayerType().GetNames();			var items = names.Select((v, i)=> new ListObject(i, v)).ToList();			return	new ListObjectCollection(items);		}		set {			Console.WriteLine("SpriteFillColorCage > ListObjectCollection > SET:{0}", value.SelectedItem);			if (value.SelectedItem != null) SelectedComponent = value.SelectedItem;		} 	}// Converterpublic class ListObjectCollectionConverter:StringConverter {	// combobox names list	private List<string> names = new List<string>();	// collection instance	private ListObjectCollection collection;	// constructor	public ListObjectCollectionConverter() => collection = new ListObjectCollection();	//true means show a combobox	public override bool GetStandardValuesSupported(ITypeDescriptorContext context) {		return true;	}	//true will limit to list. false will show the list, 	//but allow free-form entry	public override bool GetStandardValuesExclusive(ITypeDescriptorContext context) {		return true;	}	// chack if input value is correct type	public override bool CanConvertFrom(ITypeDescriptorContext context, Type sourceType) {		if (sourceType == typeof(string)) {			return true;		}		return base.CanConvertFrom(context, sourceType);	}	// when user select an item	public override object ConvertFrom(ITypeDescriptorContext context, CultureInfo culture, object value) {		//Console.WriteLine("ListObjectCollectionConverter > ConvertFrom > Value:{0}", value);		if (value is string s) {			// conversion logic goes here			collection.SelectedItem = collection.GetItemByName(s);			return collection;		}		return base.ConvertFrom(context, culture, value);	}	// get string list in to listbox	public override TypeConverter.StandardValuesCollection GetStandardValues(ITypeDescriptorContext context) {		//Console.WriteLine("ListObjectCollectionConverter > GetStandardValues > Dict:\n\t{0}", Names.ListToString("\n\t"));		return new StandardValuesCollection(names);	}	// select property(Name, Index, etc...) which will shown in the listbox	public override object ConvertTo(ITypeDescriptorContext context, CultureInfo culture, object value, Type destinationType) {		// show names in list		var label = "";		if (value is ListObjectCollection loc) {						if (collection.Count == 0) {				collection = loc;				names = loc.GetNames();			}			//Console.WriteLine("ListObjectCollectionConverter > ConvertTo >\n\tNames:{0}\n\tSelectedName:{1}", names.ListToString(), collection.SelectedItem.Name);			label = collection.SelectedItem.Name;		} else if (value is string s) {			//Console.WriteLine("ListObjectCollectionConverter > ConvertTo >  String:{0}", s);			label = s;		}		//Console.WriteLine("ListObjectCollectionConverter > ConvertTo > other value:{0}", value);		//return base.ConvertTo(context, culture, value, destinationType);		return label;	}}public class ListObjectCollectionConverter:StringConverter {	// combobox names list	private List<string> names = new List<string>();	// collection instance	private ListObjectCollection collection;	// constructor	public ListObjectCollectionConverter() => collection = new ListObjectCollection();	//true means show a combobox	public override bool GetStandardValuesSupported(ITypeDescriptorContext context) {		return true;	}	//true will limit to list. false will show the list, 	//but allow free-form entry	public override bool GetStandardValuesExclusive(ITypeDescriptorContext context) {		return true;	}	// chack if input value is correct type	public override bool CanConvertFrom(ITypeDescriptorContext context, Type sourceType) {		if (sourceType == typeof(string)) {			return true;		}		return base.CanConvertFrom(context, sourceType);	}	// when user select an item	public override object ConvertFrom(ITypeDescriptorContext context, CultureInfo culture, object value) {		//Console.WriteLine("ListObjectCollectionConverter > ConvertFrom > Value:{0}", value);		if (value is string s) {			// conversion logic goes here			collection.SelectedItem = collection.GetItemByName(s);			return collection;		}		return base.ConvertFrom(context, culture, value);	}	// get string list in to listbox	public override TypeConverter.StandardValuesCollection GetStandardValues(ITypeDescriptorContext context) {		//Console.WriteLine("ListObjectCollectionConverter > GetStandardValues > Dict:\n\t{0}", Names.ListToString("\n\t"));		return new StandardValuesCollection(names);	}	// select property(Name, Index, etc...) which will shown in the listbox	public override object ConvertTo(ITypeDescriptorContext context, CultureInfo culture, object value, Type destinationType) {		// show names in list		var label = "";		if (value is ListObjectCollection loc) {						if (collection.Count == 0) {				collection = loc;				names = loc.GetNames();			}			//Console.WriteLine("ListObjectCollectionConverter > ConvertTo >\n\tNames:{0}\n\tSelectedName:{1}", names.ListToString(), collection.SelectedItem.Name);			label = collection.SelectedItem.Name;		} else if (value is string s) {			//Console.WriteLine("ListObjectCollectionConverter > ConvertTo >  String:{0}", s);			label = s;		}		//Console.WriteLine("ListObjectCollectionConverter > ConvertTo > other value:{0}", value);		//return base.ConvertTo(context, culture, value, destinationType);		return label;	}}using System;using System.Collections.Generic;using System.Linq;namespace NetComponents.objs {	/// <summary> ListObject </summary>	public class ListObject {		/// <summary> Ingeger cell index in range 0 - int.MaxValue </summary>		public int Index { get; set; }		/// <summary> String cell name </summary>		public string Name { get; set; }		/// <summary> ListObject with index and name </summary>		public ListObject(int index, string name) {						Index = index;			Name = name;		}		/// <summary> Return ListObject as string </summary>		public override string ToString() {			return String.Format("(ListObject){{ Index:{0} Name:{1} }}", Index, Name);		}	}	/// <summary> Collection of ListObject items </summary>	public class ListObjectCollection {		/// <summary> Collection of ListObject items </summary>		public List<ListObject> Items;		/// <summary> Get-Set selected item in collection </summary>		public ListObject SelectedItem { get; set; }		/// <summary> Create a collection of ListObject Items </summary>		public ListObjectCollection() => Items = new List<ListObject>();		/// <summary> Create a collection of ListObject Items </summary>		public ListObjectCollection(List<ListObject> items) {			Items = items;			if (Items.Count > 0) SelectedItem = Items.First();		}		/// <summary> Get collection items count </summary>		public int Count => Items.Count;		/// <summary> Get names from items in collection </summary>		public List<string> GetNames() => Items.Select(x => x.Name).ToList();		/// <summary> Get item by name </summary>		public ListObject GetItemByName(string name) => Items.FirstOrDefault(itm => itm.Name == name);	}}